// Text — Gtk.Text
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles text with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { InputHints, InputPurpose } from "@/lib/enums"

export interface TextProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.Text */
  activatesDefault?: boolean

  /** Pango.AttrList, from Gtk.Text */
  attributes?: ReactNode

  /** EntryBuffer, from Gtk.Text */
  buffer?: ReactNode

  /** gboolean, from Gtk.Text */
  enableEmojiCompletion?: boolean

  /** Gio.MenuModel, from Gtk.Text */
  extraMenu?: ReactNode

  /** utf8, from Gtk.Text */
  imModule?: string

  /** InputHints, from Gtk.Text */
  inputHints?: InputHints[]

  /** InputPurpose, from Gtk.Text */
  inputPurpose?: InputPurpose

  /** guint, from Gtk.Text */
  invisibleChar?: number

  /** gboolean, from Gtk.Text */
  invisibleCharSet?: boolean

  /** gint, from Gtk.Text */
  maxLength?: number

  /** gboolean, from Gtk.Text */
  overwriteMode?: boolean

  /** utf8, from Gtk.Text */
  placeholderText?: string

  /** gboolean, from Gtk.Text */
  propagateTextWidth?: boolean

  /** Pango.TabArray, from Gtk.Text */
  tabs?: ReactNode

  /** gboolean, from Gtk.Text */
  truncateMultiline?: boolean

  /** gboolean, from Gtk.Text */
  visibility?: boolean
}

export function Text({ className, children, placeholderText }: TextProps) {
  return (
    <div className={cn("p-1.5", "min-h-7.5", "opacity-100", "text-[inherit]", "bg-[transparent]", "font-[var(--monospace-font-family)]", "text-[smaller]", "min-w-7.5", className)}>
      {placeholderText}
      {children}
    </div>
  )
}
